// These are prospective eager-BF16 component gates, not SDPA equivalence tests.
// Ordinary host tests skip before any CUDA initialization through the shared
// newAFMoENativeDevice helper. An explicitly enabled native gate fails if CUDA
// is unavailable. No expected values are generated by the GPU implementation.
func TestAFMoENativeAttention(t *testing.T) {
	dev := newAFMoENativeDevice(t)
	m, err := compileAfmoeAttentionModule(dev)
	if m != nil {
		t.Cleanup(func() {
			if err := m.Close(); err != nil {
				t.Error(err)
			}
		})
	}
	if err != nil {
		t.Fatal(err)
	}
	t.Run("cast before norm weight head128", func(t *testing.T) { afmoeNativeHeadNorm(t, dev, m) })
	t.Run("half split rope head128", func(t *testing.T) { afmoeNativeAttentionRoPE(t, dev, m) })
	t.Run("gqa local global and gate", func(t *testing.T) { afmoeNativeGQAAttention(t, dev, m) })
	t.Run("sigmoid single opmath discriminator", func(t *testing.T) {
		out := afmoeNativeUpload(t, dev, []float32{1})
		gate := afmoeNativeUpload(t, dev, []float32{0.005859375})
		if err := m.emitGate(out, gate, afmoeNativeEmit(dev)); err != nil {
			t.Fatal(err)
		}
		afmoeNativeSync(t, dev)
		// Independent witness: sigmoid(3/512) rounds to BF16 0.5.
		// Rounding exp and addition separately to BF16 incorrectly gives
		// 0.50390625; the general one-ULP tolerance would admit that bug.
		checkAfmoeAttentionValues(t, afmoeNativeDownload(t, out), []float32{0.5})
	})
	t.Run("window2048 boundary head128", func(t *testing.T) { afmoeNativeAttentionWindow(t, dev, m) })
}

func afmoeNativeHeadNorm(t *testing.T, dev *cuda.Device, m *afmoeAttentionModule) {
	var fixture struct {
		Norm struct {
			Input, Weight, Expected afmoeAttentionTensor
			Eps                     float32
		} `json:"rms_norm"`
	}
	data, err := os.ReadFile("testdata/afmoe-mini/reference.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	f := fixture.Norm
	if len(f.Input.Data) != 4 || len(f.Weight.Data) != 4 || len(f.Expected.Data) != 4 {
		t.Fatal("invalid independent RMS fixture")
	}
	const heads, dim = 4, 128
	input, weight, want := make([]float32, heads*dim), make([]float32, dim), make([]float32, heads*dim)
	for d := range weight {
		weight[d] = f.Weight.Data[d%4]
	}
	for h := 0; h < heads; h++ {
		for d := 0; d < dim; d++ {
			input[h*dim+d] = f.Input.Data[d%4]
			want[h*dim+d] = f.Expected.Data[d%4]
		}
	}
	x, w := afmoeNativeUpload(t, dev, input), afmoeNativeUpload(t, dev, weight)
	if err := m.emitHeadNorm(x, w, heads, dim, f.Eps, afmoeNativeEmit(dev)); err != nil {
		t.Fatal(err)
	}
	afmoeNativeSync(t, dev)
	// Strict BF16 equality retains the fixture's cast-before-weight
	// discriminator. A one-ULP allowance here would admit the wrong operation.
	checkAfmoeAttentionValues(t, afmoeNativeDownload(t, x), want)
}

func afmoeNativeAttentionRoPE(t *testing.T, dev *cuda.Device, m *afmoeAttentionModule) {
	f := readAfmoeAttentionFixture(t).RoPE
	if len(f.Input.Data) != 4 || len(f.Expected.Data) != 4 {
		t.Fatal("invalid independent RoPE fixture")
	}
	const heads, dim = 4, 128
	input, want := make([]float32, heads*dim), make([]float32, heads*dim)
	// Frequencies at d=0 and d=32 in a 128-wide head have exponents0 and1/2,
	// exactly the frequencies of the independent four-wide fixture. This
	// embeds its nontrivial half-split discriminator in full Mini-width heads.
	for h := 0; h < heads; h++ {
		for j, d := range []int{0, 32, 64, 96} {
			input[h*dim+d] = f.Input.Data[j]
			want[h*dim+d] = f.Expected.Data[j]
		}
	}
	x := afmoeNativeUpload(t, dev, input)
	if err := m.emitRoPE(x, heads, dim, f.Pos, f.Theta, afmoeNativeEmit(dev)); err != nil {
		t.Fatal(err)
	}
	afmoeNativeSync(t, dev)
	afmoeNativeAttentionNear(t, afmoeNativeDownload(t, x), want)
}

func afmoeNativeGQAAttention(t *testing.T, dev *cuda.Device, m *afmoeAttentionModule) {
	f := readAfmoeAttentionFixture(t).Attention
	s := afmoeAttentionShape{f.Heads, f.KVHeads, f.HeadDim}
	if s.Heads*s.HeadDim != 8 || s.KVHeads != 2 || f.Pos != 3 {
		t.Fatal("invalid independent GQA fixture")
	}
	for _, tc := range []struct {
		name   string
		window int
		want   afmoeAttentionExpected
	}{
		{"local", 2048, f.Local},
		{"global NoPE", 0, f.Global},
	} {
		t.Run(tc.name, func(t *testing.T) {
			// The fixture contains independent normalized/rotated Q and K.
			// In the global case they have no RoPE. Its query width8 differs
			// from the hidden width4, and two Q heads share each KV head.
			q := afmoeNativeUpload(t, dev, flattenAfmoeAttention(tc.want.Query))
			k := afmoeNativeUpload(t, dev, flattenAfmoeAttentionCache(tc.want.Keys))
			v := afmoeNativeUpload(t, dev, flattenAfmoeAttentionCache(f.Values))
			out := afmoeNativeUpload(t, dev, make([]float32, s.Heads*s.HeadDim))
			gate := afmoeNativeUpload(t, dev, f.Gate.Data)
			if err := m.emitDecode(q, k, v, out, s, f.Pos, tc.window, afmoeNativeEmit(dev)); err != nil {
				t.Fatal(err)
			}
			afmoeNativeSync(t, dev)
			afmoeNativeAttentionNear(t, afmoeNativeDownload(t, out), tc.want.Ungated)
			if err := m.emitGate(out, gate, afmoeNativeEmit(dev)); err != nil {
				t.Fatal(err)
			}
			afmoeNativeSync(t, dev)
			afmoeNativeAttentionNear(t, afmoeNativeDownload(t, out), tc.want.Gated)
		})
	}
}

func afmoeNativeAttentionWindow(t *testing.T, dev *cuda.Device, m *afmoeAttentionModule) {
	f := readAfmoeAttentionFixture(t).Window
	s := afmoeAttentionShape{4, 2, 128}
	if f.Pos != 2049 || f.Window != 2048 || f.Count != 2050 || f.Local.Start != 2 || f.Local.Count != 2048 {
		t.Fatal("invalid independent window fixture")
	}
	stride := s.KVHeads * s.HeadDim
	query := make([]float32, s.Heads*s.HeadDim)
	keys, values := make([]float32, f.Count*stride), make([]float32, f.Count*stride)
	for h := 0; h < s.Heads; h++ {
		query[h*s.HeadDim] = 1
	}
	for text, rows := range f.Markers {
		pos, err := strconv.Atoi(text)
		if err != nil {
			t.Fatal(err)
		}
		for h, row := range rows {
			copy(values[pos*stride+h*s.HeadDim:], row)
		}
	}
	for _, tc := range []struct {
		name   string
		window int
		local  bool
		want   afmoeAttentionWindowWant
	}{
		{"global uniform analytic", 0, false, f.Global},
		{"local excludes nonzero keys0and1", f.Window, true, f.Local},
	} {
		t.Run(tc.name, func(t *testing.T) {
			khost := append([]float32(nil), keys...)
			if tc.local {
				// Excluded keys carry large nonzero scores. Accidentally
				// retaining either key changes the output substantially;
				// allowed keys retain the independent uniform expectation.
				for pos := 0; pos < 2; pos++ {
					for h := 0; h < s.KVHeads; h++ {
						khost[pos*stride+h*s.HeadDim] = 64
					}
				}
			}
			q := afmoeNativeUpload(t, dev, query)
			k := afmoeNativeUpload(t, dev, khost)
			v := afmoeNativeUpload(t, dev, values)
			out := afmoeNativeUpload(t, dev, make([]float32, len(query)))
			if err := m.emitDecode(q, k, v, out, s, f.Pos, tc.window, afmoeNativeEmit(dev)); err != nil {
				t.Fatal(err)
			}
			afmoeNativeSync(t, dev)
			want := make([]float32, len(query))
			for h := 0; h < s.Heads; h++ {
				copy(want[h*s.HeadDim:], tc.want.Ungated.Data[h*2:h*2+2])
			}
			checkAfmoeAttentionValues(t, afmoeNativeDownload(t, out), want)
		})
	}
}

// afmoeNativeAttentionNear permits one BF16 ULP at the expected magnitude,
// plus1e-6 absolute for values near zero. It rejects nonfinite values and
// requires every output to be BF16-rounded. This prospective bound permits
// expf/powf/reduction variation; it is not a full-model correctness waiver.
func afmoeNativeAttentionNear(t *testing.T, got, want []float32) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("length %d, want %d", len(got), len(want))
	}
	for i, x := range got {
		if !afmoeFinite(want[i]) {
			t.Fatalf("nonfinite expected value[%d] = %g", i, want[i])
		}
		if !afmoeFinite(x) || afmoeBF16(x) != x {
			t.Errorf("value[%d] = %g is not finite BF16", i, x)
			continue
		}
		bits := safetensors.Float32ToBFloat16(float32(math.Abs(float64(want[i]))))
		var ulp float64
		if bits == 0x7f7f {
			prev := safetensors.BFloat16ToFloat32(bits - 1)
			ulp = math.Abs(float64(want[i])) - float64(prev)
		} else {
			next := safetensors.BFloat16ToFloat32(bits + 1)
			ulp = float64(next) - math.Abs(float64(want[i]))
		}
		if math.Abs(float64(x-want[i])) > ulp+1e-6 {
			t.Errorf("value[%d] = %g, want %g within one BF16 ULP (%g) +1e-6", i, x, want[i], ulp)
		}
	}
}
